import{_ as o,o as e,c as d,a2 as r}from"./chunks/framework.CnHmQiA8.js";const p=JSON.parse('{"title":"快速上手","description":"","frontmatter":{"title":"快速上手","outline":[2,3]},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795441506000}'),l={name:"guide/getting-started.md"};function a(i,t,n,s,c,g){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p><strong>教学案制作（TeachingPlan）</strong> 是一款面向教师的桌面排版工具：把题目、知识点、插图与教师解析放进同一份 <code>.tplan</code> 工程，预览确认页数与版式后，一键同时导出**教师版（教案）<strong>与</strong>学生版（学案）**两个 Word 文档。</p><h2 id="_1-认识首页与教学案库" tabindex="-1">1. 认识首页与教学案库 <a class="header-anchor" href="#_1-认识首页与教学案库" aria-label="Permalink to &quot;1. 认识首页与教学案库&quot;">​</a></h2><p>启动软件后进入类似 WPS 的首页，左侧栏分为常用操作与文件导航两部分：</p><ul><li><strong>快捷创建与打开</strong>：<code>新建教学案</code>、<code>从 Word 文档新建</code>、<code>从墨案导入…</code>、<code>打开</code></li><li><strong>文件浏览</strong>： <ul><li><strong>最近</strong>：快速打开近期编辑过的教学案</li><li><strong>教学案库</strong>：默认路径为 <code>文档\\教学案</code>，可以在其中新建子文件夹（例如按年级、章节分类）</li><li><strong>本地目录</strong>：直接浏览桌面、文档、下载与电脑各磁盘</li></ul></li></ul><p>右侧文件列表支持以下操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>快捷方式 / 入口</th></tr></thead><tbody><tr><td>打开教学案（或双击 Word 直接新建）</td><td>双击文件 或 <code>Enter</code></td></tr><tr><td>重命名（同步修改 <code>.tplan</code> 真实文件名）</td><td>右键 → 重命名 或 <code>F2</code></td></tr><tr><td>删除（移入系统回收站）</td><td>右键 → 删除 或 <code>Delete</code></td></tr><tr><td>导出 Word / 在文件夹中显示</td><td>右键文件（或点条目右侧 <code>⋯</code>）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">文件在软件外被移动或删除了？</p><p>在“最近”列表中右键失效条目选择 <strong>从列表中移除</strong>，或直接点击顶部的 <strong>清除失效项</strong> 即可整理干净。</p></div><h2 id="_2-新建第一份教学案" tabindex="-1">2. 新建第一份教学案 <a class="header-anchor" href="#_2-新建第一份教学案" aria-label="Permalink to &quot;2. 新建第一份教学案&quot;">​</a></h2><ol><li>在首页点击 <strong>新建教学案</strong>。</li><li>输入教学案名称，并选择一份 <strong>格式预设</strong>（例如 <code>物理教学案 V1.0</code> 或 <code>数学教学案 V1.0</code>）。</li><li>确认后软件会在教学案库中立即创建 <code>.tplan</code> 工程，并自动带入模板默认的页眉（Logo、电话、水印），随后进入编辑界面。</li></ol><h3 id="多标签页同时处理多份教学案" tabindex="-1">多标签页同时处理多份教学案 <a class="header-anchor" href="#多标签页同时处理多份教学案" aria-label="Permalink to &quot;多标签页同时处理多份教学案&quot;">​</a></h3><ul><li>每打开一份教学案会在顶部占一个标签页，点击标签可切换（<code>Ctrl+Tab</code> / <code>Ctrl+Shift+Tab</code>）。</li><li>支持拖动标签调整排列顺序，点击标签上的 <code>×</code> 或用鼠标中键关闭（<code>Ctrl+W</code>）。</li><li>名称前带圆点表示尚未保存；点击左上角 <strong>首页</strong> 可以返回首页查看文件，同时保留已打开的标签页。</li></ul><h2 id="_3-熟悉三栏编辑界面" tabindex="-1">3. 熟悉三栏编辑界面 <a class="header-anchor" href="#_3-熟悉三栏编辑界面" aria-label="Permalink to &quot;3. 熟悉三栏编辑界面&quot;">​</a></h2><p>进入教学案后，界面分为左、中、右三栏（拖动分隔边界可自由调整左右栏宽度，双击边界恢复默认）：</p><ol><li><strong>左侧大纲</strong>：按大标题、栏目、题型分组、知识点与题目树状展示结构；点击大纲中的某一项，中间预览会自动滚动到它第一行所在位置（停在预览窗约 20% 高度处，方便看清整道题）。</li><li><strong>中间分页预览</strong>：真实按 A4 纸张大小与页边距分页渲染，<strong>预览效果与导出的 Word 保持一致</strong>。顶部可以切换查看「学生版」或「教师版」预览效果。</li><li><strong>右侧属性面板</strong>：选中某道题、知识点或标题后，在这里填写和修改具体内容。点击预览中的任意一行，右侧属性栏也会自动滚到对应输入框附近。</li></ol><div class="info custom-block"><p class="custom-block-title">题目属性的“题目”页与“仅教师版”页</p><p>每道题右侧属性面板顶部都有两个切换页：</p><ul><li><strong>题目</strong>：难度、变式题、题干、题图、选项、小问与版式；</li><li><strong>仅教师版</strong>：重点题标记、答案（及答案插图）、知识点、重点、难点、审题、解析（及解析插图）。</li></ul><p>在预览中点击答案或解析时会自动切到“仅教师版”，点击题干或选项时自动切回“题目”。</p></div><h2 id="_4-一键导出教师版与学生版-word" tabindex="-1">4. 一键导出教师版与学生版 Word <a class="header-anchor" href="#_4-一键导出教师版与学生版-word" aria-label="Permalink to &quot;4. 一键导出教师版与学生版 Word&quot;">​</a></h2><p>完成编辑后，点击顶栏 <strong>导出 Word</strong>（快捷键 <code>Ctrl+E</code>），或者在首页右键某个教学案直接选择 <strong>导出 Word</strong>：</p><ul><li><strong>教师版（教案）</strong>：默认命名为 <code>(T)名称.docx</code>，包含题目、答案、解析、审题、重点题标记等完整内容；</li><li><strong>学生版（学案）</strong>：默认命名为 <code>(S)名称.docx</code>，隐藏答案与解析，并按设定的“整题同页”与“作答留白”排出留空；若使用知识点手册或题型整理预设，学生版还会自动将重点挖空成下划线或虚线书写格。</li><li><strong>知识点重点难点汇总（可选）</strong>：在导出对话框勾选后，还会额外生成一份 <code>(T)名称(知识点重点难点).docx</code>，按栏目汇总各题的知识点、重点、难点与审题（可在首页 <code>设置…</code> 中设为默认勾选）。</li></ul><p>导出生成的 Word 文档沿用模板样式，题号、小问号与 <code>【答案】</code> 等标签均为 Word 自动编号，公式为 Word 原生公式、表格为 Word 表格，发给其他老师也能继续直接编辑。</p>',20)])])}const u=o(l,[["render",a]]);export{p as __pageData,u as default};
